import { expect, test, uniqueName } from "../../fixtures";

const API_TEXT = (expiry: string) => `Coverage Amount: $2,000,000\nExpiry Date: ${expiry}\n`;

function isoDateInDays(days: number): string {
  const d = new Date();
  d.setUTCHours(0, 0, 0, 0);
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().slice(0, 10);
}

const EXAMPLES = [
  { days: 0, include: true },
  { days: 30, include: true },
  { days: 31, include: false },
];

test.describe("insurance expiry flag", () => {
  for (const { days, include } of EXAMPLES) {
    test(`insurance expiring in ${days} days ${include ? "includes" : "does not include"} insurance_expiring_soon`, { tag: "@REV-08" }, async ({ apiAs }) => {
      // Arrange
      const member = await apiAs("member");
      const created = await member.post("/api/vendors", {
        data: {
          name: uniqueName("REV-08 Vendor"),
          category: "services",
          contact_email: `rev08.${Date.now()}.${Math.random().toString(36).slice(2, 8)}@northwind-vendors.com`,
        },
      });
      expect(created.status(), await created.text()).toBe(201);
      const vendor = (await created.json()) as { id: string };

      const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "insurance_certificate",
          file: {
            name: "insurance.txt",
            mimeType: "text/plain",
            buffer: Buffer.from(API_TEXT(isoDateInDays(days))),
          },
        },
      });
      expect(upload.status(), await upload.text()).toBe(201);

      // Extraction runs in the background; flags are only computed once it has finished.
      await expect
        .poll(async () => {
          const res = await member.get(`/api/vendors/${vendor.id}/documents`);
          const docs = (await res.json()) as { kind: string; status: string }[];
          return docs.find((d) => d.kind === "insurance_certificate")?.status;
        }, { timeout: 60_000 })
        .toBe("extracted");

      // Act
      const response = await member.get(`/api/vendors/${vendor.id}`);

      // Assert
      expect(response.status(), await response.text()).toBe(200);
      const body = (await response.json()) as { flags: string[] };
      expect(body.flags).toEqual(include ? ["insurance_expiring_soon"] : []);
    });
  }
});
